//! Parity tests against the Go original (`reference/go/charm-banner`).
//!
//! The golden file `tests/golden/banner.txt` is generated by the Go program
//! `reference/go/charm-banner/cmd/parity`, which dumps every glyph of the
//! three fonts and a set of rendered banners. The Rust side rebuilds the very
//! same dump, so the comparison is byte-for-byte.
//!
//! Regenerate the golden file with:
//!
//! ```text
//! cargo run -p charm-parity --bin charm-parity -- gen \
//!     crates/charm-banner/tests/golden/banner.txt -- \
//!     go run ./reference/go/charm-banner/cmd/parity
//! ```

use std::fmt::Write as _;

use charm_banner::{render, Font, RenderOption};
use charm_parity::assert_golden;

/// The fonts of the Go original: name, font, height and nominal width.
const FONTS: [(&str, Font, usize, usize); 3] = [
    ("small", Font::Small, 3, 3),
    ("medium", Font::Medium, 5, 5),
    ("large", Font::Large, 7, 7),
];

/// The rendered banners compared by the parity harness.
const CASES: [(Font, bool, &str); 17] = [
    (Font::Medium, false, "HELLO"),
    (Font::Medium, false, "RUST"),
    (Font::Small, false, "RUST"),
    (Font::Large, false, "RUST"),
    (Font::Medium, false, "ABC 123"),
    (Font::Medium, false, "aBc"),
    (Font::Medium, false, ""),
    (Font::Medium, false, "É"),
    (Font::Medium, false, "AÉB"),
    (Font::Medium, false, "ß"),
    (Font::Medium, false, "Hello, World!"),
    (Font::Small, true, "HI"),
    (Font::Medium, false, "0123456789"),
    (Font::Large, false, "go!"),
    (Font::Small, false, " "),
    (Font::Large, true, "Charm Suite!"),
    (Font::Large, false, "a-b:c.d!e"),
];

#[test]
fn banner_matches_the_go_implementation() {
    assert_golden("banner", &dump());
}

#[test]
fn every_glyph_of_every_font_is_byte_identical_to_the_go_one() {
    // The dump contains the rows of every glyph of the three fonts; comparing
    // it with the golden file proves that the extracted font data is
    // byte-identical to the Go one.
    let dump = dump();
    let glyph_lines = dump
        .lines()
        .filter(|line| line.starts_with("GLYPH ") || line.starts_with("FALLBACK "))
        .count();

    // 3 fonts x (1 space glyph + 94 printable ASCII characters).
    assert_eq!(glyph_lines, 3 * 95);

    for (name, font, height, _) in FONTS {
        let section = font_section(&dump, name);
        assert!(!section.is_empty(), "secao ausente: {name}");
        for (key, pattern) in font.glyphs() {
            let expected = format!(
                "{} {key}|{}|",
                if is_fallback(font, *key) {
                    "FALLBACK"
                } else {
                    "GLYPH"
                },
                pattern.rows.join("|")
            );
            assert!(
                section.contains(&expected),
                "glifo `{key}` da fonte {name} diverge do Go"
            );
        }
        assert_eq!(font.height(), height);
    }
}

#[test]
fn rendered_banners_match_the_go_implementation() {
    let dump = dump();
    for (font, bold, text) in CASES {
        let mut opts = vec![RenderOption::Font(font)];
        if bold {
            opts.push(RenderOption::Style(lipgloss::Style::new().bold(true)));
        }
        let rendered = render(text, &opts);
        for row in rendered.split('\n') {
            let line = format!("ROW|{row}|");
            assert!(
                dump.contains(&line),
                "linha `{line}` ausente no dump para o texto `{text}`"
            );
        }
    }
}

/// Builds the very same dump as the Go program `cmd/parity`.
fn dump() -> String {
    let mut out = String::new();

    for (name, font, height, width) in FONTS {
        let _ = writeln!(out, "### FONT {name} height={height} width={width}");

        let space = rows_of(font, ' ');
        let key = ' ';
        let _ = writeln!(out, "GLYPH {key}|{}|", space.join("|"));

        for code in 0x21u8..=0x7E {
            let ch = char::from(code);
            let upper = ch.to_uppercase().to_string();
            let rows = rows_of(font, upper.chars().next().unwrap_or(ch));
            let label = if rows == space { "FALLBACK" } else { "GLYPH" };
            let _ = writeln!(out, "{label} {ch}|{}|", rows.join("|"));
        }
    }

    for (font, bold, text) in CASES {
        let mut opts = vec![RenderOption::Font(font)];
        let style = if bold { "bold" } else { "plain" };
        if bold {
            opts.push(RenderOption::Style(lipgloss::Style::new().bold(true)));
        }
        let _ = writeln!(out, "### RENDER {} {style} {}", font.name(), escape(text));
        for row in render(text, &opts).split('\n') {
            let _ = writeln!(out, "ROW|{row}|");
        }
    }

    out
}

/// The rows rendered for a single character.
fn rows_of(font: Font, ch: char) -> Vec<String> {
    let rendered = render(&ch.to_string(), &[RenderOption::Font(font)]);
    rendered.split('\n').map(str::to_owned).collect()
}

/// Whether a character is rendered as the space fallback.
///
/// The Go program labels a character as `FALLBACK` when its rendered rows are
/// the ones of the space glyph, which happens for every character without a
/// glyph of its own.
fn is_fallback(font: Font, ch: char) -> bool {
    const EMPTY_ROWS: &[&str] = &[];
    if ch == ' ' {
        // The space glyph is always present in every font.
        return false;
    }
    let space: &[&str] = font.glyphs().get(&' ').map_or(EMPTY_ROWS, |p| p.rows);
    match font.glyphs().get(&ch) {
        Some(pattern) => pattern.rows == space,
        None => true,
    }
}

/// The section of the dump that belongs to a font.
fn font_section(dump: &str, name: &str) -> String {
    let start = dump
        .lines()
        .position(|line| line.starts_with(&format!("### FONT {name} ")))
        .unwrap_or(0);
    dump.lines()
        .skip(start + 1)
        .take_while(|line| !line.starts_with("### "))
        .collect::<Vec<_>>()
        .join("\n")
}

/// Escapes a string the same way the Go program does.
fn escape(text: &str) -> String {
    let mut out = String::with_capacity(text.len() + 2);
    out.push('"');
    for ch in text.chars() {
        match ch {
            '\\' => out.push_str("\\\\"),
            '"' => out.push_str("\\\""),
            '\n' => out.push_str("\\n"),
            '\t' => out.push_str("\\t"),
            '\r' => out.push_str("\\r"),
            c if (c as u32) < 0x20 => {
                let _ = write!(out, "\\x{:02x}", c as u32);
            }
            c => out.push(c),
        }
    }
    out.push('"');
    out
}
